let d = $input.item.json;
let records = [];
if (d.data && Array.isArray(d.data.leads)) records = d.data.leads;
else if (Array.isArray(d.data)) records = d.data;
else if (Array.isArray(d)) records = d;
return { records: records, count: records.length, firstId: records.length ? records[0].id : null, firstName: records.length ? records[0].name : null, firstStage: records.length ? records[0].stage : null, rawResponse: d };

let d = $input.item.json;
let rec = null;
if (d.data) {
  if (d.data.createLead) rec = d.data.createLead;
  else if (d.data.updateLead) rec = d.data.updateLead;
  else if (d.data.lead) rec = d.data.lead;
  else if (d.data.id) rec = d.data;
}
if (!rec && d.id) rec = d;
const webhookLeadId = ($('CRM Lead Webhook').item.json.body && $('CRM Lead Webhook').item.json.body.lead && $('CRM Lead Webhook').item.json.body.lead.leadId) || null;
const leadId = (rec && rec.id) ? rec.id : webhookLeadId;
let leadAction = 'updated';
try { const _ = $('Create Lead').item; leadAction = 'created'; } catch (e) {}
return { leadId: leadId, leadAction: leadAction, rawResponse: d };
